 const ROTAS_M3 = [
   { metodo: 'GET', rota: '/encontros/enc_inexistente/codigo' },
   { metodo: 'POST', rota: '/encontros/enc_inexistente/presencas' },
   { metodo: 'POST', rota: '/encontros/enc_inexistente/presencas/manual' },
